import type { ButtonProps } from '@packages/ui/Button';

import type { ReactNode } from 'react';

export type UserMenuProps = Pick<ButtonProps, 'variant' | 'size' | 'look'> & {
  /** In a header the menu opens below its trigger; in a sidebar, to its right. */
  placement: 'header' | 'sidebar';
  /** The sign-in page, which a signed-out visitor's Sign in button opens. */
  signInHref: string;
  /** More rows between the user's name and Sign out: `Dropdown.Item`s, such as Settings. */
  children?: ReactNode;
  /** Styles the trigger, or the Sign in button when signed out; `variant`, `size` and `look` style the Sign in button. */
  className?: string;
};

/**
 * UserMenu: the account in a header or a sidebar, from the app's session.
 * Signed in, it shows the user's avatar and name and opens a menu: the name,
 * your rows, then Sign out, which signs out. Signed out, it shows a Sign in
 * button. While the saved session is read it shows nothing, so a signed-in
 * user never sees Sign in flash.
 *
 * When not to use:
 * - Signing up: the page's own call to action, such as the landing page's.
 * - Actions on a record: a Dropdown beside the record.
 *
 * Pitfalls:
 * - The scaffold places it where the theme puts the account: keep it there,
 *   with its `placement` and `signInHref`.
 * - `placement` matches where it sits: `header` opens the menu below,
 *   `sidebar` to the right of a sidebar's footer.
 * - Children are `Dropdown.Item`s. Sign out is already there, last.
 * - Restyle it with `className`, and the Sign in button with `variant`,
 *   `size` and `look`; the menu and its rows keep their behavior.
 */
import { UserMenu } from '@app/components/UserMenu';
import { Dropdown } from '@packages/ui/Dropdown';
import { Settings } from 'lucide-react';
import { useRouter } from 'next/navigation';
import React from 'react';

// Usage: the patterns to copy.
/** In a header: the menu opens below, with a row of your own above Sign out. */
const InHeader = () => {
  const router = useRouter();
  return (
    <UserMenu placement="header" signInHref="/sign-in">
      <Dropdown.Item
        leftIcon={<Settings />}
        onSelect={() => router.push('/settings')}
      >
        Settings
      </Dropdown.Item>
    </UserMenu>
  );
};

/** In a sidebar's footer: the menu opens to the right. */
const InSidebar = () => <UserMenu placement="sidebar" signInHref="/sign-in" />;

export default function UserMenuRecipe() {
  return (
    <div className="flex-col-gap-4 items-start">
      <InHeader />
      <InSidebar />
    </div>
  );
}

import { PageLogo } from '@app/components/PageLogo';
import React from 'react';

/**
 * The left end of the public site's header bar.
 *
 * Put here, in this order:
 * - The logo. Code places `PageLogo` here when the theme puts the logo at
 *   the left. Keep it first, as it is.
 * - Links to the site's own pages or sections, when the theme puts them
 *   here. Use one `NextLink` from `@app/components/NextLink` with
 *   `look="plain"` per link. Example: Features, Pricing.
 *   Each link opens a route from `.weave/01-scaffold/routes.json`.
 *
 * PageLayout draws the bar and lays these items in a row. Return only the
 * items: no wrapper, height, padding, background or border.
 *
 * Never put here:
 * - An H1, a page's title or a page's actions. They go in the page's
 *   `PageHeader`.
 *
 * The line "The theme puts here" below names this app's items. Build those
 * and nothing else.
 *
 * The theme puts here: It holds: logo.
 */
export const MarketingHeaderLeftSlot = () => {
  return (
    <PageLogo />
  );
};

import { UserMenu } from '@app/components/UserMenu';
import React from 'react';

/**
 * The right end of the public site's header bar.
 *
 * Put here, in this order:
 * - Sign up, as the main action. Use `Button as={NextLink}` with
 *   `href="/sign-up"`. Leave it out when the landing page's hero already
 *   offers it.
 * - The account. Code places `UserMenu` here when the theme puts the
 *   account at the right. It shows Sign in to a visitor and the account
 *   menu to a member. Keep it last, as it is.
 *
 * PageLayout draws the bar and lays these items in a row. Return only the
 * items: no wrapper, height, padding, background or border.
 *
 * Never put here:
 * - A page's own actions. They go in the page's `PageHeader`.
 *
 * The line "The theme puts here" below names this app's items. Build those
 * and nothing else.
 *
 * The theme puts here: It holds: account.
 */
export const MarketingHeaderRightSlot = () => {
  return (
    <UserMenu placement="header" signInHref="/sign-in" />
  );
};

