// packages/ui/src/SidebarMenu/SidebarMenu.recipe.tsx
// Covers: SidebarMenu, SidebarMenuItem

/**
 * SidebarMenu: a sidebar's navigation. Its `header` holds what sits above
 * the list, like the logo, a search or a Create button, its `footer` what
 * sits below it, like the account and sign out, and the rows between them
 * are SidebarMenuItems, one per destination, which scroll when there are
 * more than fit. It fills the height the sidebar gives it, so the
 * sidebar sets that height: the one under the app's header.
 *
 * When not to use:
 * - A header's main navigation: a row of the app's NextLinks.
 * - A menu of actions behind a button: Dropdown. Sections of one page: Tabs.
 * - Records the user browses: a list or a Table on the page, not the sidebar.
 *
 * Pitfalls:
 * - The sidebar sets the height; SidebarMenu takes all of it. Without a
 *   height nothing scrolls and the footer sits right under the last row.
 * - `selected` comes from the current route (`usePathname()` in the Next
 *   app); it marks the row `aria-current="page"`.
 * - `as` takes a link component, the app's NextLink, with its `href`; the
 *   row's children are the label.
 * - Rows are links. Anything else in the sidebar, like the logo, a search, a
 *   Create button or Sign out, goes in `header` or `footer`, never in a row.
 *   Each of those pieces sits in its own `SidebarMenuItem as="div"`, so it
 *   lines up with the links; never pad or wrap it yourself.
 * - The sidebar wears the frame's background (`bg-surface-frame`); the rows
 *   are colored for it.
 */
import { Avatar } from '@packages/ui/Avatar';
import { Button, IconButton } from '@packages/ui/Button';
import { Link } from '@packages/ui/Link';
import { SidebarMenu, SidebarMenuItem } from '@packages/ui/SidebarMenu';
import { Tag } from '@packages/ui/Tag';
import { Truncate } from '@packages/ui/Truncate';
import { LayoutDashboard, LogOut, Plus, Settings, Star } from 'lucide-react';
import React, { type ReactNode, useState } from 'react';

// Setup: stand-ins for your app's data and requests, not part of the pattern.
const dashboards = [
  { id: 'd1', name: 'Morning routine' },
  { id: 'd2', name: 'Deep work' },
  { id: 'd3', name: 'Evening wind down' },
];

const many = Array.from({ length: 24 }, (_, i) => ({
  id: `p${i + 1}`,
  name: `Project ${i + 1}`,
}));

/** Stands in for the sidebar of an app frame: the frame sets its width and the height under the header. */
const Sidebar = ({ children }: { children: ReactNode }) => (
  <div
    className="bg-surface-frame p-4"
    style={{
      // The frame's sidebar width; this box stands in for it.
      width: 264,
      // The height under the app's header, so a long list scrolls.
      height: 360,
    }}
  >
    {children}
  </div>
);

// Usage: the patterns to copy.
/**
 * An app sidebar: the frame's Create in the header, one row per dashboard
 * with the current one selected, and the account with sign out in the
 * footer, which stays at the bottom. The header's and footer's pieces sit in
 * `as="div"` rows, lined up with the links.
 */
const AppSidebar = () => {
  const [current, setCurrent] = useState('d1');

  return (
    <Sidebar>
      <SidebarMenu
        aria-label="Dashboards"
        header={
          <SidebarMenuItem as="div">
            <Button leftIcon={<Plus />} className="w-full">
              Create
            </Button>
          </SidebarMenuItem>
        }
        footer={
          <SidebarMenuItem as="div">
            <Avatar size="sm" name="Ada Lovelace" />
            <Truncate>ada@example.com</Truncate>
            <IconButton tooltip="Sign out">
              <LogOut />
            </IconButton>
          </SidebarMenuItem>
        }
      >
        {dashboards.map((dashboard) => (
          <SidebarMenuItem
            key={dashboard.id}
            href={`/dashboards/${dashboard.id}`}
            leftIcon={<LayoutDashboard />}
            selected={dashboard.id === current}
            onClick={(event) => {
              event.preventDefault();
              setCurrent(dashboard.id);
            }}
          >
            {dashboard.name}
          </SidebarMenuItem>
        ))}
      </SidebarMenu>
    </Sidebar>
  );
};

/**
 * In the Next app, each row is the app's NextLink with `as`, so the route
 * changes without a reload; Link stands in for it here.
 */
const WithNextLink = () => (
  <Sidebar>
    <SidebarMenu aria-label="Settings">
      <SidebarMenuItem
        as={Link}
        href="/settings/profile"
        selected
        leftIcon={<Settings />}
      >
        Profile
      </SidebarMenuItem>
      <SidebarMenuItem as={Link} href="/settings/plan" leftIcon={<Star />}>
        Plan
      </SidebarMenuItem>
    </SidebarMenu>
  </Sidebar>
);

/**
 * More rows than fit: the list scrolls between the header and the footer,
 * which keep their place.
 */
const Scrolling = () => (
  <Sidebar>
    <SidebarMenu
      aria-label="Projects"
      header={
        <SidebarMenuItem as="div">
          <Button className="w-full">New project</Button>
        </SidebarMenuItem>
      }
      footer={
        <SidebarMenuItem as="div">
          <Truncate>24 projects</Truncate>
        </SidebarMenuItem>
      }
    >
      {many.map((project) => (
        <SidebarMenuItem key={project.id} href={`/projects/${project.id}`}>
          {project.name}
        </SidebarMenuItem>
      ))}
    </SidebarMenu>
  </Sidebar>
);

/**
 * A count at the end of a row with `rightAddOn`, and a label too long for the
 * row, cut with the whole of it in a tooltip.
 */
const CountsAndLongLabels = () => (
  <Sidebar>
    <SidebarMenu aria-label="Folders">
      <SidebarMenuItem href="/folders/inbox" rightAddOn={<Tag>12</Tag>}>
        Inbox
      </SidebarMenuItem>
      <SidebarMenuItem href="/folders/conference" rightAddOn={<Tag>3</Tag>}>
        Spring conference planning with the whole design team
      </SidebarMenuItem>
    </SidebarMenu>
  </Sidebar>
);

export default function SidebarMenuRecipe() {
  return (
    <div className="flex-row-gap-6 flex-wrap items-start">
      <AppSidebar />
      <WithNextLink />
      <Scrolling />
      <CountsAndLongLabels />
    </div>
  );
}

// packages/ui/src/Button/Button.recipe.tsx
// Covers: Button, IconButton, PlainButton

/**
 * Button: an action the user takes: save, publish, delete, open a menu.
 * `default` is the main action of a view (one per view), `base` a secondary
 * one, `danger` one that deletes or can't be undone: filled, it is the
 * confirm dialog's button, and on a list row a delete is as quiet as the
 * row's other actions. `look="ghost"` makes any of them quiet, for toolbars
 * and rows, where an action is an IconButton with a tooltip. IconButton is
 * an action shown as an icon alone; PlainButton makes a non-button element,
 * like an info icon or an avatar, act as a button.
 *
 * When not to use:
 * - Going to another page: Link. In the Next app, a route is the app's
 *   NextLink, and one that must look like a button is
 *   `Button as={NextLink}`.
 * - A toggle that shows whether it's on: Chip.
 * - Two `default` buttons in one view: make the lesser one `base`.
 *
 * Pitfalls:
 * - `type` defaults to "button". A form's submit needs `type="submit"`.
 * - Deleting a row removes the button that had focus: move focus on, to a
 *   stable button, with a `ref`.
 * - IconButton needs a `tooltip`; a string one is its accessible name. Add
 *   `aria-label` or `aria-labelledby` only when the name must differ from
 *   what the tooltip shows, like "Delete Design review" under "Delete".
 * - Say why a button can't be used: `disabledWithReason`,
 *   `readOnlyWithReason`, `loadingWithReason`. A bare `disabled` leaves the
 *   user guessing.
 */
import { Avatar } from '@packages/ui/Avatar';
import { Button, IconButton, PlainButton } from '@packages/ui/Button';
import { Controller, Form } from '@packages/ui/Form';
import { Input } from '@packages/ui/Input';
import { Copy, Info, Play, Plus, Settings, Trash2 } from 'lucide-react';
import React, { useEffect, useId, useRef, useState } from 'react';
import { useForm } from 'react-hook-form';

// Setup: stand-ins for your app's data and requests, not part of the pattern.
const saveEvent = (draft: EventDraft) =>
  new Promise<EventDraft>((resolve) => setTimeout(() => resolve(draft), 800));

// Usage: the patterns to copy.
type EventDraft = { title: string };

/**
 * Saving a form: `type="submit"` makes the button send the form, and
 * `loading` follows `formState.isSubmitting`, so it can't be pressed twice.
 * The result is announced through a status region.
 */
const SaveForm = () => {
  const [saved, setSaved] = useState('');
  const { control, handleSubmit, reset, formState } = useForm<EventDraft>({
    defaultValues: { title: '' },
  });

  return (
    <Form
      onSubmit={handleSubmit(async (draft) => {
        const result = await saveEvent(draft);
        setSaved(`Saved "${result.title}"`);
      })}
      actions={
        <>
          <Button variant="base" onClick={() => reset()}>
            Reset
          </Button>
          <Button
            type="submit"
            // Saving takes a moment and the status above reports the result.
            loading={formState.isSubmitting}
          >
            Save
          </Button>
        </>
      }
    >
      <Controller
        name="title"
        control={control}
        rules={{ required: 'Enter the event title' }}
      >
        {({ field }) => (
          <Input label="Event title" autoComplete="off" {...field} />
        )}
      </Controller>
      <p role="status">{saved}</p>
    </Form>
  );
};

/** A form's actions: the main one last, the secondary one `base`. */
const FormActions = () => (
  <div className="flex-row-gap-2 flex-wrap">
    <Button variant="base">Cancel</Button>
    <Button>Publish</Button>
  </div>
);

/**
 * Icons: `leftIcon` before the label, `rightIcon` after it. Icons are
 * decoration; the text names the button.
 */
const WithIcons = () => (
  <div className="flex-row-gap-2 flex-wrap">
    <Button leftIcon={<Plus />}>New event</Button>
    <Button variant="base" rightIcon={<Play />}>
      Start session
    </Button>
  </div>
);

/**
 * A key hint: `rightAddOn` takes an element, hidden from screen readers
 * because `aria-keyshortcuts` announces the key. The shortcut itself must
 * work, so a key listener runs the action.
 */
const WithShortcut = () => {
  const [count, setCount] = useState(0);

  useEffect(() => {
    const onKeyDown = (event: KeyboardEvent) => {
      const target = event.target as HTMLElement;
      if (event.key !== 'n' || event.ctrlKey || event.metaKey) return;
      if (target.closest('input, textarea, [contenteditable]')) return;
      setCount((current) => current + 1);
    };

    window.addEventListener('keydown', onKeyDown);
    return () => window.removeEventListener('keydown', onKeyDown);
  }, []);

  return (
    <div className="flex-col-gap-2 items-start">
      <Button
        aria-keyshortcuts="N"
        rightAddOn={<kbd aria-hidden>N</kbd>}
        onClick={() => setCount((current) => current + 1)}
      >
        New event
      </Button>
      <p role="status">Events created: {count}</p>
    </div>
  );
};

/**
 * Tooltip: detail on hover and focus, read as the description. With a
 * disabled reason, both show, the tooltip first.
 */
const WithTooltip = () => (
  <div className="flex-row-gap-2 flex-wrap">
    <Button tooltip="Sends the event to every subscriber">Publish</Button>
    <Button
      tooltip="Sends the event to every subscriber"
      disabledWithReason="Add a date before publishing"
    >
      Publish
    </Button>
  </div>
);

/**
 * Unavailable: `disabledWithReason` disables it and says why. Read-only
 * (`readOnlyWithReason`) keeps the button visible but inert, for a view the
 * user may not change.
 */
const Unavailable = () => (
  <div className="flex-row-gap-2 flex-wrap">
    <Button disabledWithReason="Add a date before publishing">Publish</Button>
    <Button readOnlyWithReason="Only organizers can edit the schedule">
      Edit schedule
    </Button>
    <Button
      // The page shows no draft yet, so the reason is plain.
      disabled
    >
      Discard draft
    </Button>
  </div>
);

/**
 * Busy: `loading` shows a spinner in place of the icon and the button can't
 * be pressed again until it's done. `loadingWithReason` also says what is
 * happening, to sighted users on hover and in a status region for screen
 * readers. Set one of the two, not both.
 */
const Busy = () => {
  const [syncing, setSyncing] = useState(false);

  return (
    <div className="flex-row-gap-2 flex-wrap">
      <Button
        loadingWithReason={syncing ? 'Syncing the attendee list' : undefined}
        onClick={() => {
          setSyncing(true);
          setTimeout(() => setSyncing(false), 1500);
        }}
      >
        Sync attendees
      </Button>
      <Button loadingWithReason="Exporting the guest list">
        Export guests
      </Button>
    </div>
  );
};

/**
 * Play and stop in one button: `disableWhileLoading={false}` keeps it
 * pressable while loading, so the press that started it can stop it.
 */
const RunAndStop = () => {
  const [running, setRunning] = useState(false);

  return (
    <Button
      leftIcon={<Play />}
      // It stays pressable, and the label changes to Stop.
      loading={running}
      disableWhileLoading={false}
      onClick={() => setRunning(!running)}
    >
      {running ? 'Stop' : 'Run'}
    </Button>
  );
};

/**
 * Keeping focus after a delete: the removed row's button disappears, so a
 * `ref` on a stable button moves focus there.
 */
const DeleteRow = () => {
  const [sessions, setSessions] = useState(['Opening keynote', 'Workshop']);
  const addRef = useRef<HTMLButtonElement>(null);

  return (
    <div className="flex-col-gap-2 items-start">
      <ul aria-label="Sessions" className="flex-col-gap-2">
        {sessions.map((session) => (
          <li key={session} className="flex-row-gap-2 items-center">
            {session}
            <IconButton
              variant="danger"
              look="ghost"
              tooltip="Delete"
              aria-label={`Delete ${session}`}
              onClick={() => {
                addRef.current?.focus();
                setSessions((current) =>
                  current.filter((entry) => entry !== session),
                );
              }}
            >
              <Trash2 />
            </IconButton>
          </li>
        ))}
      </ul>
      <Button
        ref={addRef}
        leftIcon={<Plus />}
        onClick={() => setSessions((current) => [...current, 'New session'])}
      >
        Add session
      </Button>
    </div>
  );
};

/**
 * Icon only: IconButton, named by its `tooltip`, which shows on hover and
 * focus. Sizes `xs`, `sm` (the default) and `md`. `loading` and
 * `disabledWithReason` work as on Button.
 */
const IconOnly = () => (
  <div className="flex-row-gap-2 flex-wrap items-center">
    <IconButton variant="base" look="ghost" size="xs" tooltip="Event settings">
      <Settings />
    </IconButton>
    <IconButton variant="base" tooltip="Event settings">
      <Settings />
    </IconButton>
    <IconButton size="md" variant="danger" tooltip="Delete event">
      <Trash2 />
    </IconButton>
    <IconButton loadingWithReason="Duplicating event" tooltip="Duplicate event">
      <Copy />
    </IconButton>
    <IconButton
      disabledWithReason="Cancelled events can't be copied"
      tooltip="Duplicate event"
    >
      <Copy />
    </IconButton>
  </div>
);

/**
 * A name that differs from the tooltip: `aria-labelledby` points at visible
 * text, here the row's title, and `aria-label` gives a fuller name, like
 * "Duplicate Design review" under the tooltip "Duplicate".
 */
const IconNames = () => {
  const titleId = useId();

  return (
    <div className="flex-row-gap-2 items-center">
      <span id={titleId}>Design review</span>
      <IconButton aria-labelledby={titleId} tooltip="Settings">
        <Settings />
      </IconButton>
      <IconButton aria-label="Duplicate Design review" tooltip="Duplicate">
        <Copy />
      </IconButton>
    </div>
  );
};

/**
 * An info icon that shows details below it: PlainButton makes its one child,
 * a non-interactive element, focusable and pressable by Enter and Space, with
 * the look the child already has, its focus style included. Name it with
 * `aria-label`; `aria-expanded` and `aria-controls` say what it opens. For a
 * styled action use IconButton.
 */
const InfoIcon = () => {
  const [open, setOpen] = useState(false);
  const detailsId = useId();

  return (
    <div className="flex-col-gap-2 items-start">
      <PlainButton
        aria-label="About ticket types"
        aria-expanded={open}
        aria-controls={detailsId}
        onClick={() => setOpen(!open)}
      >
        <span>
          <Info aria-hidden />
        </span>
      </PlainButton>
      <p id={detailsId} hidden={!open}>
        VIP includes the speaker dinner.
      </p>
    </div>
  );
};

/**
 * An avatar that does something when pressed, like showing a person's
 * details. Avatar hides itself from assistive tech, so the `span` around it
 * is the button, and `aria-label` names it.
 */
const OrganizerAvatar = () => {
  const [contact, setContact] = useState('');

  return (
    <div className="flex-row-gap-2 items-center">
      <PlainButton
        aria-label="Show contact details for Grace Hopper"
        onClick={() => setContact('Grace Hopper, grace@example.com')}
      >
        <span>
          <Avatar name="Grace Hopper" />
        </span>
      </PlainButton>
      <p role="status">{contact}</p>
    </div>
  );
};

export default function ButtonRecipe() {
  return (
    <div className="flex-col-gap-4 items-start">
      <SaveForm />
      <FormActions />
      <WithIcons />
      <WithShortcut />
      <WithTooltip />
      <Unavailable />
      <Busy />
      <RunAndStop />
      <DeleteRow />
      <IconOnly />
      <IconNames />
      <InfoIcon />
      <OrganizerAvatar />
    </div>
  );
}

// packages/ui/src/Toast/Toast.recipe.tsx
// Covers: dismissToast, toast, updateToast

/**
 * toast: a short message at the corner of the screen about something that
 * just happened, like "Session saved", that closes on its own. Call it from
 * anywhere, React or not: it returns the toast's id. updateToast changes a
 * showing toast, dismissToast closes one, clearToasts closes all.
 *
 * When not to use:
 * - An error the user must fix in a form: the field's `error`.
 * - A question that needs an answer: openConfirmationDialog.
 * - Something that must stay on screen, like a sold-out notice: text on the
 *   page itself.
 *
 * Pitfalls:
 * - UIRoot renders the toasts: without it, a toast shows nowhere.
 * - The title is one line and truncates: put details in `description`.
 * - An `action` needs `altText`: how to do the same without the toast, as a
 *   screen reader may hear the toast after it has gone.
 * - A `loading` toast stays until updateToast or dismissToast: always end it.
 * - updateToast and dismissToast do nothing for an unknown or closed id, and
 *   `onClose` runs once, however the toast closes.
 */
import { Button } from '@packages/ui/Button';
import {
  clearToasts,
  dismissToast,
  toast,
  updateToast,
} from '@packages/ui/Toast';
import React, { useState } from 'react';

// Setup: stand-ins for your app's requests, not part of the pattern.
const publishSchedule = (fail: boolean) =>
  new Promise<void>((resolve, reject) => {
    setTimeout(() => (fail ? reject(new Error('Offline')) : resolve()), 800);
  });

// Usage: the patterns to copy.
/** After an action: `status` sets the icon; `info` without it. */
const SaveSession = () => (
  <Button
    onClick={() =>
      toast({
        title: 'Session saved',
        description: 'Attendees see the new time at once.',
        status: 'success',
      })
    }
  >
    Save session
  </Button>
);

/**
 * A request in flight: a `loading` toast that updateToast turns into the
 * outcome, which then closes on its own.
 */
const PublishSchedule = ({ fail = false }: { fail?: boolean }) => (
  <Button
    variant="base"
    onClick={async () => {
      const id = toast({ title: 'Publishing the schedule', status: 'loading' });
      try {
        await publishSchedule(fail);
        updateToast(id, { title: 'Schedule published', status: 'success' });
      } catch {
        updateToast(id, {
          title: 'Couldn’t publish the schedule',
          description: 'Check your connection and try again.',
          status: 'error',
        });
      }
    }}
  >
    {fail ? 'Publish, offline' : 'Publish schedule'}
  </Button>
);

/**
 * An action that undoes what just happened. `altText` tells screen readers
 * where else to do it; pressing the action closes the toast.
 */
const RemoveSpeaker = () => {
  const [removed, setRemoved] = useState(false);

  const remove = () => {
    setRemoved(true);
    toast({
      title: 'Speaker removed',
      action: {
        label: 'Undo',
        altText: 'Add them back from the speakers list',
        onClick: () => setRemoved(false),
      },
    });
  };

  return (
    <Button variant="base" onClick={remove}>
      {removed ? 'Removed' : 'Remove speaker'}
    </Button>
  );
};

/**
 * A toast that waits for the user: `duration={Infinity}` and a close button.
 * dismissToast closes it from code; `onClose` learns either way.
 */
const ConnectionLost = () => {
  const [id, setId] = useState<string>();

  const show = () =>
    setId(
      toast({
        title: 'Connection lost',
        description: 'Changes are saved once you’re back online.',
        status: 'warning',
        duration: Infinity,
        closable: true,
        onClose: () => setId(undefined),
      }),
    );

  return id ? (
    <Button variant="base" onClick={() => dismissToast(id)}>
      Back online
    </Button>
  ) : (
    <Button variant="base" onClick={show}>
      Go offline
    </Button>
  );
};

/** From code outside any component, like leaving a page: clear them all. */
const leaveEditor = () => clearToasts();

export default function ToastRecipe() {
  return (
    <div className="flex-row-gap-3 flex-wrap">
      <SaveSession />
      <PublishSchedule />
      <PublishSchedule fail />
      <RemoveSpeaker />
      <ConnectionLost />
      <Button variant="base" onClick={leaveEditor}>
        Clear all
      </Button>
    </div>
  );
}

