// packages/ui/src/Dropdown/Dropdown.recipe.tsx
// Covers: Dropdown

/**
 * Dropdown: a menu of actions or choices behind a trigger button, with menu
 * roles, focus and keyboard built in (arrows, typeahead, Escape). Write a row
 * as a `Dropdown.Item`, an on/off row as a `Dropdown.CheckboxItem`, one
 * choice of several as a `Dropdown.RadioItem` in a `Dropdown.RadioGroup`.
 * Group rows with `Dropdown.Group`, open a submenu from a `Dropdown.Item`
 * inside `Dropdown.SubMenu`. `showCheckbox` and `showCheckmark` set how
 * checked rows show. The trigger is one focusable element that forwards its
 * props: `Dropdown.Button`, an `IconButton` named for what the menu holds,
 * or for an avatar a `PlainButton` around the Avatar, as the Avatar recipe
 * shows; never an Avatar inside an IconButton. Tab closes the menu, back to
 * the trigger.
 *
 * Not for navigation (use `Link`, the app's NextLink for its routes), one
 * on/off toggle (`Button` or `Chip`), a form value (`Select`) or free-form
 * content (`Popover`).
 *
 * Pitfalls: an `onSelect` that calls `event.preventDefault()` keeps the menu
 * open; an item whose children aren't plain text needs `textValue`; a menu
 * holds only items, so no buttons or links inside it.
 */
import { Avatar } from '@packages/ui/Avatar';
import { IconButton } from '@packages/ui/Button';
import { Dropdown } from '@packages/ui/Dropdown';
import {
  ArrowUpDown,
  Copy,
  Ellipsis,
  Link,
  Pencil,
  Trash2,
  UserPlus,
} from 'lucide-react';
import React, { useState } from 'react';

// Setup: stand-ins for your app's data and requests, not part of the pattern.
const event: EventRow = { id: 'e1', name: 'Design Summit' };

const speakers = ['Ada Lovelace', 'Grace Hopper', 'Alan Turing'];

const fakeSave = () => new Promise<void>((resolve) => setTimeout(resolve, 800));

// Usage: the patterns to copy.
type EventRow = { id: string; name: string };

/**
 * Actions on a table row. An `IconButton` trigger is named per row, so a
 * screen reader hears which event the menu is for; its `tooltip` shows the
 * short name. Each item runs its own `onSelect` once.
 */
const RowActions = ({ row }: { row: EventRow }) => {
  const [status, setStatus] = useState('');

  return (
    <div className="flex-row-gap-2 items-center">
      <Dropdown
        menu={
          <>
            <Dropdown.Item
              leftIcon={<Pencil />}
              onSelect={() => setStatus(`Renaming ${row.name}`)}
            >
              Rename
            </Dropdown.Item>
            <Dropdown.Item
              leftIcon={<Copy />}
              onSelect={() => setStatus(`Duplicated ${row.name}`)}
            >
              Duplicate
            </Dropdown.Item>
            <Dropdown.Separator />
            <Dropdown.Item
              leftIcon={<Trash2 />}
              onSelect={() => setStatus(`Cancelled ${row.name}`)}
            >
              Cancel event
            </Dropdown.Item>
          </>
        }
      >
        <IconButton
          variant="base"
          look="ghost"
          aria-label={`Actions for ${row.name}`}
          tooltip="Actions"
        >
          <Ellipsis />
        </IconButton>
      </Dropdown>
      <p role="status">{status}</p>
    </div>
  );
};

/**
 * Groups, a separator and a submenu. A `Dropdown.Group` without a `label`
 * only sets rows apart; the submenu's trigger is a `Dropdown.Item`, which gets
 * the chevron. `disabledWithReason` keeps an item or submenu visible and says
 * why it can't be used.
 */
const EventMenu = () => {
  const [status, setStatus] = useState('');

  return (
    <div className="flex-row-gap-2 items-center">
      <Dropdown
        menu={
          <>
            <Dropdown.Group label="Edit">
              <Dropdown.Item
                leftIcon={<Pencil />}
                onSelect={() => setStatus('Renaming the event')}
              >
                Rename
              </Dropdown.Item>
              <Dropdown.Item
                leftIcon={<Copy />}
                onSelect={() => setStatus('Event duplicated')}
              >
                Duplicate
              </Dropdown.Item>
            </Dropdown.Group>
            <Dropdown.Separator />
            <Dropdown.Group>
              <Dropdown.SubMenu
                menu={
                  <>
                    <Dropdown.Item
                      leftIcon={<Link />}
                      onSelect={() => setStatus('Link copied')}
                    >
                      Copy link
                    </Dropdown.Item>
                    <Dropdown.Item
                      leftIcon={<UserPlus />}
                      disabledWithReason="Only organizers can invite attendees"
                    >
                      Invite attendees
                    </Dropdown.Item>
                  </>
                }
              >
                <Dropdown.Item>Share</Dropdown.Item>
              </Dropdown.SubMenu>
            </Dropdown.Group>
            <Dropdown.Separator />
            <Dropdown.SubMenu
              disabledWithReason="Exports open after the event ends"
              menu={<Dropdown.Item>Attendee list (CSV)</Dropdown.Item>}
            >
              <Dropdown.Item>Export</Dropdown.Item>
            </Dropdown.SubMenu>
          </>
        }
      >
        <Dropdown.Button size="md">Event</Dropdown.Button>
      </Dropdown>
      <p role="status">{status}</p>
    </div>
  );
};

/**
 * One choice of several: `Dropdown.RadioGroup` with the chosen `value` around
 * `Dropdown.RadioItem`s, the chosen one announced as checked. `textValue` is
 * what typeahead matches when a row's children (here an `Avatar`) aren't
 * text. `Dropdown.Search` filters a long list: you filter the rows, it
 * announces the count and shows the empty state. Enter picks the first match
 * and never submits a form. `onOpenChange` clears the search on close.
 */
const AssignSpeaker = () => {
  const [search, setSearch] = useState('');
  const [speaker, setSpeaker] = useState(speakers[0]);
  const matches = speakers.filter((name) =>
    name.toLowerCase().includes(search.toLowerCase()),
  );

  return (
    <Dropdown
      align="start"
      onOpenChange={(open) => {
        if (!open) setSearch('');
      }}
      menu={
        <>
          <Dropdown.Search
            label="Search speakers"
            placeholder="Search speakers"
            value={search}
            onChange={setSearch}
          />
          <Dropdown.RadioGroup value={speaker} onValueChange={setSpeaker}>
            {matches.map((name) => (
              <Dropdown.RadioItem
                key={name}
                value={name}
                textValue={name}
                leftAddOn={<Avatar name={name} size="sm" />}
              >
                {name}
              </Dropdown.RadioItem>
            ))}
          </Dropdown.RadioGroup>
        </>
      }
    >
      <Dropdown.Button>Speaker: {speaker}</Dropdown.Button>
    </Dropdown>
  );
};

/**
 * On/off options: `Dropdown.CheckboxItem` with `checked` and
 * `onCheckedChange`. Preventing the default in `onSelect` keeps the menu open,
 * so several can be toggled in a row. `showCheckbox` draws a checkbox before
 * each, `showCheckmark={false}` drops the check mark after it; with both on,
 * both show.
 */
const ViewOptions = () => {
  const [showSpeakers, setShowSpeakers] = useState(true);
  const [showVenue, setShowVenue] = useState(false);
  const keepOpen = (select: Event) => select.preventDefault();

  return (
    <Dropdown
      showCheckbox
      showCheckmark={false}
      menu={
        <Dropdown.Group label="Show on the agenda">
          <Dropdown.CheckboxItem
            checked={showSpeakers}
            onCheckedChange={setShowSpeakers}
            onSelect={keepOpen}
          >
            Speakers
          </Dropdown.CheckboxItem>
          <Dropdown.CheckboxItem
            checked={showVenue}
            onCheckedChange={setShowVenue}
            onSelect={keepOpen}
          >
            Venue
          </Dropdown.CheckboxItem>
        </Dropdown.Group>
      }
    >
      <Dropdown.Button>View</Dropdown.Button>
    </Dropdown>
  );
};

/**
 * `modal={false}` leaves the rest of the page usable while the menu is open;
 * leave it out unless that's needed. `rightIcon` replaces the chevron.
 */
const SortSessions = () => {
  const [sort, setSort] = useState('start');

  return (
    <Dropdown
      modal={false}
      align="start"
      menu={
        <Dropdown.RadioGroup
          label="Sort by"
          value={sort}
          onValueChange={setSort}
        >
          <Dropdown.RadioItem value="start">Start time</Dropdown.RadioItem>
          <Dropdown.RadioItem value="name">Session name</Dropdown.RadioItem>
        </Dropdown.RadioGroup>
      }
    >
      <Dropdown.Button rightIcon={<ArrowUpDown />}>
        Sort sessions
      </Dropdown.Button>
    </Dropdown>
  );
};

/**
 * An item that waits on work: `loadingWithReason` shows a spinner and says on
 * hover what it's doing. Preventing the default keeps the menu open, and the
 * controlled `open` closes it once the work is done.
 */
const PublishItem = () => {
  const [open, setOpen] = useState(false);
  const [isPublishing, setPublishing] = useState(false);

  return (
    <Dropdown
      open={open}
      onOpenChange={setOpen}
      menu={
        <Dropdown.Item
          loadingWithReason={isPublishing ? 'Publishing the agenda' : undefined}
          onSelect={(select) => {
            select.preventDefault();
            setPublishing(true);
            void fakeSave().then(() => {
              setPublishing(false);
              setOpen(false);
            });
          }}
        >
          Publish agenda
        </Dropdown.Item>
      }
    >
      <Dropdown.Button>Agenda</Dropdown.Button>
    </Dropdown>
  );
};

/**
 * The whole menu unavailable: `disabledWithReason` on the Dropdown disables
 * the trigger and says why in its tooltip. `loadingWithReason` shows a spinner
 * on the trigger and says why; `disableWhileLoading={false}` keeps the menu
 * usable meanwhile.
 */
const MenuStates = () => (
  <div className="flex-row-gap-2 flex-wrap">
    <Dropdown
      disabledWithReason="Sign in to manage tickets"
      menu={<Dropdown.Item>Refund ticket</Dropdown.Item>}
    >
      <Dropdown.Button>Tickets</Dropdown.Button>
    </Dropdown>
    <Dropdown
      loadingWithReason="Loading the venue map"
      disableWhileLoading={false}
      menu={<Dropdown.Item>Open venue map</Dropdown.Item>}
    >
      <Dropdown.Button>Venue</Dropdown.Button>
    </Dropdown>
  </div>
);

export default function DropdownRecipe() {
  return (
    <div className="flex-col-gap-4 items-start">
      <RowActions row={event} />
      <EventMenu />
      <AssignSpeaker />
      <ViewOptions />
      <SortSessions />
      <PublishItem />
      <MenuStates />
    </div>
  );
}

// packages/ui/src/Truncate/Truncate.recipe.tsx
// Covers: Truncate, useTruncation

/**
 * Truncate: one line of text that ends in an ellipsis when it doesn't fit,
 * with the full text in a tooltip. Controls already truncate their labels;
 * use it for other single-line text: names, titles, table cells. For your
 * own element, `useTruncation` gives the same cut and tells whether it's cut.
 *
 * When not to use:
 * - Text that should wrap or clamp to several lines: Truncate is one line.
 * - Inline in a sentence: Truncate is always a block, so it can't cut a
 *   phrase in the middle of a line.
 *
 * Pitfalls:
 * - The tooltip is hover and keyboard focus only: anything only it says must
 *   also be on the page.
 * - Inside a link or button, put the Truncate in the control, not the control
 *   in the Truncate: its tooltip would hold a copy of the control. The
 *   tooltip shows when the control is focused from the keyboard.
 * - A parent that is a flex item needs `min-w-0`, or it grows to the text's
 *   width and nothing is cut.
 */
import { Avatar } from '@packages/ui/Avatar';
import { PlainButton } from '@packages/ui/Button';
import { Link } from '@packages/ui/Link';
import { Truncate, useTruncation } from '@packages/ui/Truncate';
import React, { useState } from 'react';

// Setup: stand-ins for your app's data and requests, not part of the pattern.
const longTitle =
  'Quarterly planning review for the platform, design and support teams';

// Usage: the patterns to copy.
/**
 * A row: an avatar, a cut name and a date that stays whole. The row takes
 * `min-w-0` because it is a flex item itself; hover the cut text to see all
 * of it.
 */
const InARow = () => (
  <div className="flex-row-gap-2 items-center min-w-0 w-full">
    <Avatar size="sm" name="Ada Lovelace" />
    <Truncate>Ada Lovelace-Byron, Countess of Lovelace and organizer</Truncate>
    <time dateTime="2026-10-27" className="shrink-0">
      27 Oct
    </time>
  </div>
);

/**
 * A custom `tooltip` shows above the full text when it's cut, and on its own
 * when it fits. The same detail is visible in the row, so nobody depends on
 * the tooltip.
 */
const WithTooltip = () => (
  <div className="flex-col-gap-1">
    <Truncate tooltip="Starts at 10:00 in Room 4">{longTitle}</Truncate>
    <span>Starts at 10:00 in Room 4</span>
  </div>
);

/**
 * `alwaysShowTooltip` shows the text on hover even when nothing is cut: for
 * text that is shortened by the content itself, like an abbreviation you
 * expand in the tooltip.
 */
const AlwaysShowTooltip = () => (
  <Truncate alwaysShowTooltip tooltip="Design Systems Conference">
    DSC
  </Truncate>
);

/**
 * Inside a link: `inline-block max-w-full` keeps the link no wider than its
 * box, so the dotted line stays under the cut text. Focusing the link from
 * the keyboard shows the full title.
 */
const InsideLink = () => (
  <Link href="/events/42" className="inline-block max-w-full">
    <Truncate>{longTitle}</Truncate>
  </Link>
);

/**
 * Your own element: `useTruncation` returns `ref` and `className` for the
 * element that holds the text, and `truncated`. Here the text sits in a
 * PlainButton that has its own tooltip, so the cut text is added to it.
 */
const OwnElement = () => {
  const { ref, className, truncated } = useTruncation<HTMLSpanElement>();
  const [opened, setOpened] = useState(false);

  return (
    <div className="flex-col-gap-2 items-start w-full">
      <PlainButton
        tooltip={truncated && longTitle}
        onClick={() => setOpened(true)}
        className="w-full"
      >
        <span ref={ref} className={className}>
          {longTitle}
        </span>
      </PlainButton>
      <p role="status">{opened ? 'Opening the session details' : ''}</p>
    </div>
  );
};

export default function TruncateRecipe() {
  return (
    <div className="flex-col-gap-4 max-w-full">
      <InARow />
      <WithTooltip />
      <AlwaysShowTooltip />
      <InsideLink />
      <OwnElement />
    </div>
  );
}

// packages/ui/src/Typography/Typography.recipe.tsx
// Covers: Caption, Code, CodeBlock, DescriptionDetails, DescriptionList, DescriptionTerm, Kbd, List, ListItem, Mark, Paragraph, Quote, Separator, Time

/**
 * Typography: the text elements of a page, styled by the design system:
 * `Paragraph`, `Caption`, `List` with `ListItem`, `DescriptionList` with
 * `DescriptionTerm` and `DescriptionDetails`, `Quote`, `Code`, `CodeBlock`,
 * `Kbd`, `Mark`, `Separator` and `Time`.
 * - `color` (default, muted, primary or a status) replaces the color the
 *   text inherits. Every element but `Separator` takes it.
 * - `font` (ui, display or mono) replaces the font the text inherits.
 *   `Code`, `CodeBlock` and `Kbd` are always mono, and `Separator` has no
 *   text, so these four don't take it.
 * - Size and line height are fixed: the caption's for `Caption`, the
 *   surrounding text's for `Code`, `Kbd`, `Mark` and `Time`, and the body's
 *   for the others.
 *
 * When not to use:
 * - A heading: a `Section`'s title is the heading.
 * - A line between groups: a gap between them is usually enough. Use a
 *   `Separator` only where the groups need a visible line.
 * - A list of records: a `CardList` or a `Table`. A `List` is for text.
 * - Rows people sort, filter or compare across: a `Table`.
 * - A number people read and compare: a `Numeral`, inside the text element.
 *
 * Pitfalls:
 * - Spacing between paragraphs and lists comes from their parent's gap,
 *   such as `flex-col-gap-3`: the elements have no margins.
 * - `ordered` only when the order means something, such as steps.
 * - A `CodeBlock` takes the code as a string: keep its line breaks in a
 *   template literal.
 */
import { Numeral } from '@packages/ui/Numeral';
import {
  Caption,
  Code,
  CodeBlock,
  DescriptionDetails,
  DescriptionList,
  DescriptionTerm,
  Kbd,
  List,
  ListItem,
  Mark,
  Paragraph,
  Quote,
  Separator,
  Time,
} from '@packages/ui/Typography';
import React from 'react';

// Setup: stand-ins for your app's data, not part of the pattern.
const record = [
  { label: 'Created', value: '2 Nov 2026' },
  { label: 'Status', value: 'Active' },
  { label: 'Owner', value: 'Alex Morgan' },
];
const setup = `pnpm install
pnpm dev`;

// Usage: the patterns to copy.
/** Body text: paragraphs in a column, spaced by the parent's gap. */
const Text = () => (
  <div className="flex-col-gap-3">
    <Paragraph>
      A paragraph of body text, which wraps to the width of its column.
    </Paragraph>
    <Paragraph color="muted">A muted paragraph for a detail.</Paragraph>
  </div>
);

/** A small muted line on the text above it, such as when a record was made. */
const Note = () => (
  <div className="flex-col-gap-1">
    <Paragraph>Spring launch plan</Paragraph>
    <Caption>Updated 2 Nov 2026</Caption>
  </div>
);

/** Points in any order, bulleted. An item may hold a list of its own. */
const Points = () => (
  <List>
    <ListItem>First point</ListItem>
    <ListItem>
      Second point
      <List>
        <ListItem>A point under it</ListItem>
      </List>
    </ListItem>
  </List>
);

/** Steps the reader follows in order, numbered. */
const Steps = () => (
  <List ordered>
    <ListItem>Fill in the form</ListItem>
    <ListItem>Check the details</ListItem>
    <ListItem>Confirm</ListItem>
  </List>
);

/** A record's fields as label and value pairs, one pair a row. */
const Fields = () => (
  <DescriptionList>
    {record.map(({ label, value }) => (
      <div key={label}>
        <DescriptionTerm>{label}</DescriptionTerm>
        <DescriptionDetails>{value}</DescriptionDetails>
      </div>
    ))}
    <div>
      <DescriptionTerm>Items</DescriptionTerm>
      <DescriptionDetails>
        <Numeral>1,300</Numeral>
      </DescriptionDetails>
    </div>
  </DescriptionList>
);

/** Someone's words, with who said them. Without `source`, just the quote. */
const Testimonial = () => (
  <Quote source="Alex Morgan" font="display">
    Someone's words, as they said them.
  </Quote>
);

/** Code in a sentence, and lines of code on their own. */
const Commands = () => (
  <div className="flex-col-gap-3">
    <Paragraph>
      Start the app with <Code>pnpm dev</Code> once the packages are in.
    </Paragraph>
    <CodeBlock>{setup}</CodeBlock>
  </div>
);

/** A shortcut named in a sentence. */
const Shortcut = () => (
  <Paragraph>
    Press <Kbd>Ctrl K</Kbd> to search.
  </Paragraph>
);

/** A search result's line, with the words that match the search marked. */
const SearchResult = () => (
  <Paragraph>
    Spring <Mark>launch</Mark> plan
  </Paragraph>
);

/**
 * A line between two groups of text that need one, and between items in a
 * row, where the row stretches it to its height.
 */
const Groups = () => (
  <div className="flex-col-gap-3">
    <Paragraph>Delivery by courier, in 3 to 5 days.</Paragraph>
    <Separator />
    <div className="flex-row-gap-3">
      <Paragraph>2 items</Paragraph>
      <Separator orientation="vertical" />
      <Paragraph>Paid by card</Paragraph>
    </div>
  </div>
);

/**
 * A record's date or moment, from the ISO value it keeps: one format across
