 */
const Dates = () => (
  <Paragraph>
    Placed <Time value="2026-11-07" />, shipped{' '}
    <Time value="2026-11-09T10:30:00.000Z" withTime />.
  </Paragraph>
);

export default function TypographyRecipe() {
  return (
    <div className="flex-col-gap-6">
      <Text />
      <Note />
      <Points />
      <Steps />
      <Fields />
      <Testimonial />
