// packages/ui/src/Link/Link.recipe.tsx
// Covers: Link

/**
 * Link: text that takes the user to another page: another site, an email
 * (`mailto:`), a phone number (`tel:`) or a file. Inside text it has a dotted
 * line instead of an underline; a link that works as a control, such as a way
 * back, a breadcrumb or a navigation item, is `look="plain"`. In the Next
 * app, a route of the app is the app's NextLink, which looks the same and
 * navigates without reloading the page.
 *
 * When not to use:
 * - An action (save, delete, open a menu): Button. A link goes somewhere.
 * - A route of the Next app: its NextLink. One that must look like a button
 *   is `Button as={NextLink}`.
 * - A whole card that opens a page: Card with `stretchLink`.
 *
 * Pitfalls:
 * - The dotted line is for a link inside text only. A link that stands on its
 *   own as a control, such as a way back, a breadcrumb, a navigation item or a
 *   footer's links, is `look="plain"`.
 * - In the Next app, a route as Link reloads the whole page: use NextLink.
 * - `target="_blank"` needs `rel="noopener noreferrer"` and text saying it
 *   opens a new tab.
 * - Link text must make sense alone ("Event guidelines", not "Click here").
 * - Say why a link is disabled: `disabledWithReason` keeps it focusable and
 *   shows the reason on focus; a plain `disabled` link leaves the tab order.
 */
import { Link } from '@packages/ui/Link';
import React from 'react';

// Usage: the patterns to copy.
/** In a sentence: it sits inline and wraps with the text around it. */
const InText = () => (
  <p>
    Read the{' '}
    <Link href="https://example.com/code-of-conduct">code of conduct</Link>{' '}
    before you register.
  </p>
);

/**
 * Another site: Link. `target="_blank"` opens a new tab, so `rel` keeps the
 * new page from reaching this one, and visually hidden text tells screen
 * reader users.
 */
const ExternalSite = () => (
  <Link
    href="https://example.com/venues/harbor-hall"
    target="_blank"
    rel="noopener noreferrer"
  >
    Harbor Hall venue page
    <span className="sr-only"> (opens in a new tab)</span>
  </Link>
);

/**
 * A link that works as a control, here a footer's links: `look="plain"`, since
 * its place already says it is a link. The dotted line stays for links inside
 * text.
 */
const ControlLinks = () => (
  <nav aria-label="Help" className="flex-row-gap-4 flex-wrap">
    <Link look="plain" href="https://example.com/help">
      Help center
    </Link>
    <Link look="plain" href="https://example.com/status">
      Service status
    </Link>
  </nav>
);

/** An email address: `mailto:` opens the user's mail app. */
const Email = () => (
  <Link href="mailto:organizers@example.com">Email the organizers</Link>
);

/** A phone number: `tel:` offers to call it on a phone. */
const Phone = () => <Link href="tel:+31201234567">Call the venue</Link>;

/** A file: `download` saves it instead of opening it. */
const Download = () => (
  <Link href="/files/schedule.pdf" download>
    Download the schedule (PDF)
  </Link>
);

/**
 * Disabled with a reason: it can't be followed, and hovering or focusing it
 * says why.
 * `disabledWithReason` on its own disables it; `disabled` disables it
 * silently, for a link whose reason is obvious from the screen.
 */
const DisabledWithReason = () => (
  <Link
    href="/files/attendance-report.pdf"
    download
    disabledWithReason="Ready once the event has ended"
  >
    Attendance report (PDF)
  </Link>
);

export default function LinkRecipe() {
  return (
    <div className="flex-col-gap-4 items-start">
      <InText />
      <ExternalSite />
      <ControlLinks />
      <Email />
      <Phone />
      <Download />
      <DisabledWithReason />
    </div>
  );
}

// web/app/components/NextLink/NextLink.recipe.tsx
// Covers: NextLink

/**
 * NextLink: a link to a route of this app (`/events/42`). Next.js navigates
 * to it without reloading the page and prefetches it. It looks like Link,
 * which is for other sites, emails, phone numbers and files: a dotted line
 * inside text, `look="plain"` as a control.
 *
 * When not to use:
 * - Another site, an email, a phone number or a file: Link.
 * - An action (save, delete, open a menu): Button. A link goes somewhere.
 * - A whole card that opens a page: Card with `stretchLink`, and a plain
 *   NextLink on its title.
 *
 * Pitfalls:
 * - The dotted line is for a link inside text only. A link that stands on its
 *   own as a control, such as a way back, a breadcrumb or a navigation item,
 *   is `look="plain"`.
 * - A route as Link reloads the whole page: use NextLink.
 * - A route that must look like a button is `Button as={NextLink}`, not a
 *   bare NextLink, whose dotted line clashes with a button.
 * - Mark the current page in a nav with `aria-current="page"`.
 * - Say why a link is disabled: `disabledWithReason` keeps it focusable and
 *   shows the reason on focus; a plain `disabled` link leaves the tab order.
 */
import { NextLink } from '@app/components/NextLink';
import { Button } from '@packages/ui/Button';
import { Input } from '@packages/ui/Input';
import { Plus } from 'lucide-react';
import React, { useState } from 'react';

// Usage: the patterns to copy.
/** In a sentence: it sits inline and wraps with the text around it. */
const InText = () => (
  <p>
    Read the <NextLink href="/guidelines">event guidelines</NextLink> before you
    publish.
  </p>
);

/**
 * Takes `replace`, `scroll`, `prefetch` and `onNavigate`, as Next.js's `Link`
 * does; `scroll={false}` keeps the scroll position.
 */
const KeepScroll = () => (
  <NextLink href="/events/42" scroll={false}>
    Design review
  </NextLink>
);

/**
 * A way back that replaces the current history entry instead of adding
 * another one. It works as a control, so it is `plain`.
 */
const ReplaceHistory = () => (
  <NextLink look="plain" href="/events" replace>
    Back to events
  </NextLink>
);

/**
 * The current page in a navigation: `aria-current="page"` tells screen
 * readers which link they're on. The nav itself is named, and its links are
 * `plain`: they work as controls.
 */
const Navigation = () => (
  <nav aria-label="Event sections">
    <ul className="flex-row-gap-4">
      <li>
        <NextLink look="plain" href="/events/42" aria-current="page">
          Overview
        </NextLink>
      </li>
      <li>
        <NextLink look="plain" href="/events/42/sessions">
          Sessions
        </NextLink>
      </li>
      <li>
        <NextLink look="plain" href="/events/42/attendees">
          Attendees
        </NextLink>
      </li>
    </ul>
  </nav>
);

/**
 * Disabled with a reason: it can't be followed, and hovering or focusing it
 * says why.
 */
const DisabledWithReason = () => (
  <NextLink
    href="/events/42/report"
    disabledWithReason="Opens once the event has ended"
  >
    Attendance report
  </NextLink>
);

/**
 * `onNavigate` runs before a route change and can cancel it with
 * `event.preventDefault()`. Here it blocks the navigation while the title has
 * unsaved changes, and a visible message says why.
 */
const GuardedNavigation = () => {
  const [saved, setSaved] = useState('Design review');
  const [title, setTitle] = useState(saved);
  const [blocked, setBlocked] = useState(false);
  const unsaved = title !== saved;

  return (
    <div className="flex-col-gap-2 items-start">
      <Input
        label="Event title"
        autoComplete="off"
        value={title}
        onChange={setTitle}
      />
      <Button
        variant="base"
        onClick={() => {
          setSaved(title);
          setBlocked(false);
        }}
      >
        Save
      </Button>
      <NextLink
        look="plain"
        href="/events"
        onNavigate={(event) => {
          if (!unsaved) return;
          event.preventDefault();
          setBlocked(true);
        }}
      >
        Back to all events
      </NextLink>
      <p role="status">{blocked ? 'Save your changes before leaving.' : ''}</p>
    </div>
  );
};

/**
 * A route styled as a button: `Button as={NextLink}` with `href`. A disabled
 * one renders an anchor without `href`, so it can't be followed; give a
 * reason.
 */
const RouteAsButton = () => (
  <div className="flex-row-gap-2 flex-wrap">
    <Button as={NextLink} href="/events/new" leftIcon={<Plus />}>
      Create event
    </Button>
    <Button
      as={NextLink}
      href="/events/42/report"
      variant="base"
      disabledWithReason="Opens once the event has ended"
    >
      Attendance report
    </Button>
  </div>
);

export default function NextLinkRecipe() {
  return (
    <div className="flex-col-gap-4 items-start">
      <InText />
      <KeepScroll />
      <ReplaceHistory />
      <Navigation />
      <DisabledWithReason />
      <GuardedNavigation />
      <RouteAsButton />
    </div>
  );
}

